actions.script:
def zinr = context.zinr
def fromD = (fromDate ?: ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd'))
def thruD = (thruDate ?: fromD)
def ds = java.sql.Timestamp.valueOf(fromD + ' 00:00:00')
def de = java.sql.Timestamp.valueOf(thruD + ' 23:59:59')
generatedStr = ec.l10n.format(ec.user.nowTimestamp, 'dd MMM yyyy HH:mm')
periodStr = fromD + ' to ' + thruD
def _org = ec.user.getPreference("ACTIVE_ORGANIZATION")
def ef = ec.entity.find("zenith.erp.pos.PosTransactionView")
    .condition("entryDate","greater-equals",ds).condition("entryDate","less-equals",de).orderBy("-entryDate").limit(3000)
if (statusId) ef.condition("statusId", statusId)
if (_org && _org != '_NA_') ef.condition("organizationPartyId", _org)
def bills = ef.list()
def stx = (searchText ?: '').trim().toLowerCase()
if (stx) bills = bills.findAll { ((it.transactionNumber ?: '').toString().toLowerCase().contains(stx) || (it.customerName ?: '').toLowerCase().contains(stx)) }
def canon = { m -> def k=(m ?: '').toString().trim(); def lk=k.toLowerCase();
    if(lk=='cash')return 'Cash'; if(lk=='upi')return 'UPI'; if(lk=='card')return 'Card';
    if(lk=='netbanking'||lk=='net banking')return 'Net Banking'; if(lk=='wallet')return 'Wallet'; if(lk=='credit')return 'Credit'; return k }
def billIds = bills.collect { it.transactionId }
def payAgg = [:]
if (billIds) ec.entity.find("zenith.erp.pos.PosPayment").condition("transactionId","in",billIds).list().each { p ->
    def mm = payAgg.get(p.transactionId, [:]); def k = canon(p.paymentMethod); mm[k] = (mm[k] ?: 0.0G) + ((p.amount ?: 0) as BigDecimal) }
def slMap = [PtCompleted:'Completed', PtVoided:'Cancelled', PtHeld:'Pending', PtCreated:'Pending']
def num = { v -> zinr.inr(ec.l10n.format((v ?: 0) as BigDecimal, '#,##0.00')) }
def dtf = { v -> v == null ? '' : ec.l10n.format(v, 'dd-MM-yyyy HH:mm') }
def x = { v -> (v ?: '').toString().replace('&','&amp;').replace('<','&lt;').replace('>','&gt;') }
rows = bills.collect { b ->
    def creditDue = b.isCredit == 'Y' && ((b.payableAmount ?: 0) as BigDecimal) > ((b.paidAmount ?: 0) as BigDecimal)
    def pt = creditDue ? 'Credit' : (payAgg[b.transactionId] ? payAgg[b.transactionId].entrySet().max{ it.value }.key : '')
    def st = creditDue ? 'Credit' : (slMap[b.statusId] ?: b.statusId)
    [no:x(b.transactionNumber ?: b.transactionId), date:dtf(b.entryDate), term:x(b.terminalName),
     cust:x(b.customerName ?: 'Walk-in Customer'), sub:num(b.subtotal), disc:num(b.discountTotal),
     tax:num(b.totalTaxAmount), net:num(b.payableAmount), pay:x(pt),
     payColor:(pt=='UPI' ? '#3B82F6' : ((pt=='Cash'||pt=='Card'||pt=='Credit') ? '#7C3AED' : '#111827')),
     status:x(st), statusColor:(st=='Completed' ? '#059669' : (st=='Credit' ? '#7C3AED' : (st=='Cancelled' ? '#6B7280' : '#D97706')))] }
rowCountStr = bills.size().toString()
